<?php
/**
 * Implements YITH_YWPI_Spanish_Electronic_Invoice_Manager module.
 *
 * @class   YITH_YWPI_Spanish_Electronic_Invoice_Manager

 * @package YITH\PDFInvoice
 */

defined( 'ABSPATH' ) || exit;

use Bluehost\VerifactiApi\Client\ClientFactory;


class YITH_YWPI_Spanish_Electronic_Invoice_Manager {

	/**
	 * Single instance of the class
	 *
	 * @var object
	 * @since 5.0.0
	 */
	protected static $instance;


	/**
	 * Returns single instance of the class
	 *
	 * @since 5.0.0
	 */
	public static function get_instance() {
		if ( is_null( self::$instance ) ) {
			self::$instance = new self();
		}

		return self::$instance;
	}

	/** @var YITH_YWPI_Verifactu_Submission_Service|null */
	private $submission_service;

	private function __construct() {
		add_action( 'ywpi_before_create_file', array( $this, 'create_invoice' ), 10, 3 );
		add_action( 'ywpi_after_reset_document', array( $this, 'cancel_invoice' ), 10, 2 );

		add_filter( 'ywpi_template_style', array( $this, 'add_custom_style' ), 10, 4 );
		add_filter( 'ywpi_after_customer_info', array( $this, 'print_qr_code_in_template' ), 10, 4 );
		add_action( 'yith_ywpi_template_document_header', array( $this, 'print_qr_code_in_default_templates' ), 15 );

		add_action( 'ywpi_after_api_update_order', array( $this, 'validate_api_order' ), 10, 3 );
	}

	/**
	 * Get the invoice uui generated by Verifacti API
	 *
	 * @param WC_Order $order The order.
	 *
	 * @return string
	 */
	public function get_invoice_code( $order ) {
		return $order->get_meta( '_ywpi_verifacti_invoice_code' );
	}

	/**
	 * CHeck if the order has an invoice on Verifacti
	 *
	 * @param WC_Order $order The order.
	 *
	 * @return bool
	 */
	public function order_has_invoice( $order ) {
		$qr_code = $order->get_meta( '_ywpi_verifacti_qrcode' );

		return '' !== $qr_code;
	}

	/**
	 * Create an invoice on Verifacti
	 *
	 * @param YITH_Document $document The document.
	 * @param string   $extension The extension.
	 * @param string   $action The action.
	 *
	 * @return void
	 */
	public function create_invoice( $document, $extension, $action ) {

		if ( $document instanceof YITH_Invoice ) {
			$order = $document->order;
			if ( 'create' === $action ) {

				$this->get_submission_service()->submit( $order, $document );
			} elseif ( 'regenerate' === $action ) {
				$this->get_submission_service()->modify( $order, $document );
			}
		}
	}

	/**
	 * @return YITH_YWPI_Verifactu_Submission_Service
	 */
	public function get_submission_service(): YITH_YWPI_Verifactu_Submission_Service {
		if ( null === $this->submission_service ) {
			$this->submission_service = new YITH_YWPI_Verifactu_Submission_Service( $this );
		}

		return $this->submission_service;
	}

	/**
	 * Get the Verifacti client or false if it fails
	 *
	 * @return \Bluehost\VerifactiApi\Client\VerifactiClient|false
	 */
	public function get_client() {
		$connection  = YITH_YWPI_Connection::get_instance();
		$environment = $connection->get_environment();
		$api_key     = $connection->get_api_key( $environment );
		try {
			$client = ClientFactory::fromApiKey(
				$api_key,
				array(
					'environment' => $environment,
				)
			);
		} catch ( \Exception $e ) {
			wc_get_logger()->error( $e->getMessage() );

			return false;
		}

		return $client;
	}

	/**
	 * After regenerate an Invoice add again the QRCode if exists
	 *
	 * @param WC_Order|false $order The order.
	 *
	 * @return string
	 */
	public function maybe_add_qr_code_on_pdf( $order ) {
		if ( ! $order instanceof WC_Order ) {
			$qr_code = '';
		} else {
			$qr_code = $order->get_meta( '_ywpi_verifacti_qrcode' );
		}
		if ( ! $qr_code ) {
			return '';
		}

		if ( strpos( $qr_code, 'base64,' ) !== false ) {
			$qr_code = substr( $qr_code, strpos( $qr_code, 'base64,' ) + 7 );
		}

		return '<div style="margin-top:20px;margin-bottom:20px;">
				   <img src="data:image/png;base64,' . $qr_code . '" width="150" height="150" />
				</div>';

	}


	/**
	 * Add the QRCode in the template near customer info
	 *
	 * @param string   $rendered_block The rendered blockl
	 * @param array    $block The block args.
	 * @param YITH_Document $document The document.
	 * @param int      $order_id The order id.
	 *
	 * @return string
	 */
	public function print_qr_code_in_template( $rendered_block, $block, $document, $order_id ) {
		if ( isset( $_REQUEST['action'] ) && 'ywpi_template_pdf_preview' === $_REQUEST['action'] ) {
			$template_id = isset( $_REQUEST['template_id'] ) ? sanitize_text_field( wp_unslash( $_REQUEST['template_id'] ) ) : false;
			$pdf_id      = get_option( 'ywpi_pdf_custom_templates_invoice' );
			$is_invoice  = $pdf_id === $template_id;
		} else {
			$is_invoice = $document instanceof YITH_Invoice;
		}
		if ( $is_invoice ) {
			$order = wc_get_order( $order_id );

			$qr_code = $this->maybe_add_qr_code_on_pdf( $order );

			return $rendered_block . $qr_code;
		}

		return $rendered_block;
	}

	/**
	 * Show the qr code in the default templates
	 *
	 * @param YITH_Document $document The document
	 *
	 * @return void
	 */
	public function print_qr_code_in_default_templates( $document ) {
		$order = $document->order;
		$qr_code = $this->maybe_add_qr_code_on_pdf( $order );

		if( $qr_code ){
			?>
			<div style="float:left"><?php echo $qr_code;?></div>
<?php
		}
	}

	/**
	 * Add a custom style for the PDF
	 *
	 * @param string          $style The style
	 * @param string        $template The template.
	 * @param YITH_YWPI_PDF_Template_Editor $builder The builder.
	 * @param YITH_Document        $document The document.
	 *
	 * @return string
	 */
	public function add_custom_style( $style, $template, $builder, $document ) {
		if ( $document instanceof YITH_Invoice ) {
			$order = $document->order;
			if ( $this->order_has_invoice( $order ) ) {
				$style .= '.wp-block-ywpi-template-document-number{
                                margin-top:-150px!important;
							}';
			}

		}

		return $style;
	}

	/**
	 * If the order has an invoice on Verifacti, cancel it
	 *
	 * @param int    $order_id The order id.
	 * @param string $document_type The document type.
	 *
	 * @return void
	 */
	public function cancel_invoice( $order_id, $document_type ) {
		if ( 'invoice' === $document_type ) {
			$order = wc_get_order( $order_id );
			$this->get_submission_service()->cancel( $order );
		}
	}

	/**
	 * Sanitize the status
	 *
	 * @param string $status The status.
	 *
	 * @return string
	 */
	public function sanitize_status( $status ) {
		return strtolower( str_replace( ' ', '-', $status ) );
	}

	/**
	 * Validate the order before sending it to Verifacti
	 *
	 * @param  WC_Order $order The order.
	 * @param array $request The request.
	 * @param string $vat_number The vat number.
	 *
	 * @return void
	 * @throws \Exception
	 */
	public function validate_api_order( $order, $request, $vat_number ) {
		$ue_countries = WC()->countries->get_european_union_countries();
		$country      = strtoupper( $request['billing_address']['country'] );
		$company      = $request['billing_address']['company'];

		$customer_type   = $request['extensions']['ywpi/electronic-fields']['billing_receiver_type'] ?? 'private';
		$document_type   = $request['extensions']['ywpi/document-type']['billing_document_type'] ?? '';
		$document_number = $request['extensions']['ywpi/document-type']['billing_document_number'] ?? '';
		$eu_vat_not_exist = isset( $request['extensions']['ywev/eu-vat'] ) && empty( $request['extensions']['ywev/eu-vat']['billing_yweu_vat'] );
		$f2_enabled =  'yes' === get_option( 'ywpi_spanish_electronic_invoice_allow_f2_invoice' , 'no');
		$f2_threshold =  get_option( 'ywpi_spanish_electronic_invoice_allow_f2_invoice_threshold' , 400);
		$order_total = $order->get_total();
		if (
			( 'ES' === $country ||
			  ( 'private' !== $customer_type && in_array( $country, $ue_countries ) ) ) &&
			( empty( $vat_number ) && $eu_vat_not_exist )
			 ) {
			throw new \Exception( esc_html__( 'NIF/VAT is required', 'yith-woocommerce-pdf-invoice' ) );
		}

		if ( 'private' !== $customer_type && empty( $company ) ) {
			throw new \Exception( esc_html__( 'Company name is required', 'yith-woocommerce-pdf-invoice' ) );
		}

		if ( 'private' === $customer_type && 'ES' !== $country) {
			if ( empty( $document_type ) ) {
				throw new \Exception( esc_html__( 'Document type is required', 'yith-woocommerce-pdf-invoice' ) );
			}
			if ( ! in_array( $document_type, [ '03', '04', '06' ], true ) ) {
				throw new \Exception( esc_html__( 'Document type not valid', 'yith-woocommerce-pdf-invoice' ) );
			}

			if( empty( $document_number ) ) {
				throw new \Exception( esc_html__( 'Document number is required', 'yith-woocommerce-pdf-invoice' ) );
			}
		}

		$meta_to_update = [
			'billing_document_type' => $document_type,
			'billing_document_number' => $document_number,
		];

		$user = $order->get_user();

		foreach ( $meta_to_update as $meta_key => $meta_value ) {
			$order->update_meta_data( '_'.$meta_key, $meta_value );
			if( $user instanceof WP_User) {
				update_user_meta( $user->ID, $meta_key, $meta_value );
			}
		}
		$order->save();
	}
}
